def adult_names(people)
  people.select { |person| person[:age] >= 18 }
        .map { |person| person[:name] }
        .sort
end

# Usage:
p adult_names([{name: "Alice", age: 20}, {name: "Bob", age: 17}, {name: "Charlie", age: 21}]) # => ["Alice", "Charlie"]
